from collections import deque
def components(g):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=0 and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<len(g) and 0<=nb<len(g[0]) and (na,nb) not in seen and g[na][nb]!=0:
                            seen.add((na,nb)); q.append((na,nb))
                out.append(cells)
    return out
